import java.util.ArrayList;
import java.util.List;

import org.springframework.stereotype.Service;

/**
 * All messages sent so far, shared by every visit to the contact view.
 */
@Service
public class ContactMessages {

    private final List<ContactMessage> messages = new ArrayList<>();

    public synchronized void add(ContactMessage message) {
        messages.addFirst(message);
    }

    /**
     * @return a snapshot of the sent messages, newest first
     */
    public synchronized List<ContactMessage> newestFirst() {
        return List.copyOf(messages);
    }
}
