@@ -0,0 +1,182 @@
+package com.example.contact;
+
+import java.time.LocalDateTime;
+import java.time.format.DateTimeFormatter;
+import java.util.regex.Pattern;
+
+import com.example.about.AboutView;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.FlexComponent;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MESSAGE_MAX_LENGTH = 500;
+    private static final Pattern EMAIL_PATTERN = Pattern.compile(EmailValidator.PATTERN);
+    private static final DateTimeFormatter SENT_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
+
+    private final ContactMessages messages;
+
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send", e -> submit());
+    private final Grid<ContactMessage> grid = new Grid<>();
+
+    private final Dialog leaveDialog = new Dialog();
+    private ContinueNavigationAction pendingNavigation;
+    private boolean clearingFields;
+
+    public ContactView(ContactMessages messages) {
+        this.messages = messages;
+
+        // Report every keystroke, so that editing a field re-enables Send straight away
+        nameField.setValueChangeMode(ValueChangeMode.EAGER);
+        emailField.setValueChangeMode(ValueChangeMode.EAGER);
+        phoneField.setValueChangeMode(ValueChangeMode.EAGER);
+        messageField.setValueChangeMode(ValueChangeMode.EAGER);
+        nameField.addValueChangeListener(e -> onFieldEdited());
+        emailField.addValueChangeListener(e -> onFieldEdited());
+        phoneField.addValueChangeListener(e -> onFieldEdited());
+        messageField.addValueChangeListener(e -> onFieldEdited());
+
+        Shortcuts.addShortcutListener(this, this::submit, Key.ENTER).bindLifecycleTo(this);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+        grid.addColumn(m -> m.sentAt().format(SENT_FORMAT)).setHeader("Sent");
+        grid.setItems(messages.newestFirst());
+
+        leaveDialog.setHeaderTitle("Discard your message?");
+        leaveDialog.add(new Paragraph("The message you started has not been sent. Keep editing it, or discard it and leave this page."));
+        leaveDialog.setCloseOnEsc(false);
+        leaveDialog.setCloseOnOutsideClick(false);
+        Button keepEditing = new Button("Keep editing", e -> closeLeaveDialog());
+        Button discard = new Button("Discard", e -> {
+            ContinueNavigationAction navigation = pendingNavigation;
+            closeLeaveDialog();
+            navigation.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        leaveDialog.getFooter().add(keepEditing, discard);
+
+        FormLayout form = new FormLayout(nameField, emailField, phoneField, messageField);
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, sendButton, grid, leaveDialog);
+        setAlignSelf(FlexComponent.Alignment.START, sendButton);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasTypedInput()) {
+            pendingNavigation = event.postpone();
+            leaveDialog.open();
+        }
+    }
+
+    private void submit() {
+        // Enter also reaches the view while the leave dialog is open, and must not send then
+        if (sendButton.isEnabled() && !leaveDialog.isOpened() && validate()) {
+            messages.add(new ContactMessage(
+                    nameField.getValue().strip(),
+                    emailField.getValue().strip(),
+                    phoneField.getValue().strip(),
+                    messageField.getValue().strip(),
+                    LocalDateTime.now()));
+            grid.setItems(messages.newestFirst());
+            clearFields();
+            sendButton.setEnabled(false);
+            Notification.show("Message sent", 3000, Notification.Position.TOP_CENTER);
+        }
+    }
+
+    /**
+     * Marks every field that breaks a rule, and clears the marks on the others.
+     *
+     * @return true if the form may be sent
+     */
+    private boolean validate() {
+        String name = nameField.getValue().strip();
+        String email = emailField.getValue().strip();
+        String phone = phoneField.getValue().strip();
+        String message = messageField.getValue().strip();
+
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        messageField.setInvalid(false);
+
+        if (name.isEmpty()) {
+            reject(nameField, "Name is required");
+        }
+        if (email.isEmpty() && phone.isEmpty()) {
+            reject(emailField, "Give an e-mail address or a phone number");
+        } else if (!email.isEmpty() && !EMAIL_PATTERN.matcher(email).matches()) {
+            reject(emailField, "Enter a valid e-mail address");
+        }
+        if (message.isEmpty()) {
+            reject(messageField, "Message is required");
+        } else if (message.length() > MESSAGE_MAX_LENGTH) {
+            reject(messageField, "Message must be at most 500 characters");
+        }
+
+        return !nameField.isInvalid() && !emailField.isInvalid() && !messageField.isInvalid();
+    }
+
+    private static void reject(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void clearFields() {
+        clearingFields = true;
+        try {
+            nameField.clear();
+            emailField.clear();
+            phoneField.clear();
+            messageField.clear();
+        } finally {
+            clearingFields = false;
+        }
+    }
+
+    private void onFieldEdited() {
+        if (!clearingFields) {
+            sendButton.setEnabled(true);
+        }
+    }
+
+    private boolean hasTypedInput() {
+        return !nameField.isEmpty() || !emailField.isEmpty() || !phoneField.isEmpty() || !messageField.isEmpty();
+    }
+
+    private void closeLeaveDialog() {
+        pendingNavigation = null;
+        leaveDialog.close();
+    }
+}
