+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+import java.util.regex.Pattern;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Value;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @Value("${local.server.port}")
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Test
+    void emptySendShowsErrorsAndSendsNothing() {
+        page.navigate(getUrl() + "contact");
+
+        sendButton().click();
+
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByText("Give an e-mail address or a phone number")).isVisible();
+        assertThat(page.getByText("Message is required")).isVisible();
+        assertThat(page.getByText("Message sent")).not().isVisible();
+    }
+
+    @Test
+    void validFormIsSentAndListed() {
+        page.navigate(getUrl() + "contact");
+
+        field("Name").fill("Browser Ada");
+        field("Phone").fill("+358 40 1234567");
+        field("Message").fill("Hello from the browser");
+        sendButton().click();
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(field("Name")).hasValue("");
+        assertThat(field("Message")).hasValue("");
+        assertThat(sendButton()).hasAttribute("disabled", "");
+        assertThat(page.locator("vaadin-grid").getByText("Hello from the browser")).isVisible();
+    }
+
+    @Test
+    void enterSendsTheForm() {
+        page.navigate(getUrl() + "contact");
+
+        field("Name").fill("Enter Ada");
+        field("Email").fill("ada@example.com");
+        field("Message").fill("Sent with the keyboard");
+        page.keyboard().press("Enter");
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(page.locator("vaadin-grid").getByText("Sent with the keyboard")).isVisible();
+    }
+
+    @Test
+    void invalidEmailIsReportedOnTheEmailField() {
+        page.navigate(getUrl() + "contact");
+
+        field("Name").fill("Bad Mail");
+        field("Email").fill("not-an-email");
+        field("Message").fill("Hi");
+        sendButton().click();
+
+        assertThat(page.getByText("Enter a valid e-mail address")).isVisible();
+        assertThat(field("Email")).hasValue("not-an-email");
+    }
+
+    @Test
+    void typedInputAsksBeforeLeavingAndKeepEditingStaysOnTheView() {
+        page.navigate(getUrl() + "contact");
+
+        field("Name").fill("Leaving Ada");
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+        assertThat(page.getByText("Discard your message?")).isVisible();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+
+        assertThat(page.getByText("Discard your message?")).not().isVisible();
+        assertThat(field("Name")).hasValue("Leaving Ada");
+        assertThat(page).hasURL(Pattern.compile(".*/contact$"));
+    }
+
+    @Test
+    void discardGoesOnToTheAboutView() {
+        page.navigate(getUrl() + "contact");
+
+        field("Name").fill("Discarding Ada");
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+
+        assertThat(page).hasURL(Pattern.compile(".*/about$"));
+        assertThat(page.locator("h1")).hasText("About");
+    }
+
+    @Test
+    void enterInTheLeaveDialogDoesNotSendTheForm() {
+        page.navigate(getUrl() + "contact");
+
+        field("Name").fill("Dialog Ada");
+        field("Phone").fill("+358 40 1234567");
+        field("Message").fill("Must not be sent from the dialog");
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        assertThat(page.getByText("Discard your message?")).isVisible();
+        page.keyboard().press("Enter");
+        // Keep editing is a round trip to the server, so the Enter has been handled by the time it returns
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+
+        assertThat(page.getByText("Message sent")).not().isVisible();
+        assertThat(page.locator("vaadin-grid").getByText("Must not be sent from the dialog")).not().isVisible();
+        assertThat(field("Name")).hasValue("Dialog Ada");
+        assertThat(page).hasURL(Pattern.compile(".*/contact$"));
+    }
+
+    @Test
+    void browserForwardAlsoAsksBeforeLeaving() {
+        page.navigate(getUrl() + "contact");
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        assertThat(page).hasURL(Pattern.compile(".*/about$"));
+        page.goBack();
+        assertThat(page).hasURL(Pattern.compile(".*/contact$"));
+
+        field("Name").fill("History Ada");
+        page.goForward();
+
+        assertThat(page.getByText("Discard your message?")).isVisible();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+        assertThat(field("Name")).hasValue("History Ada");
+        assertThat(page).hasURL(Pattern.compile(".*/contact$"));
+    }
+
+    @Test
+    void emptyFormLeavesWithoutAsking() {
+        page.navigate(getUrl() + "contact");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+        assertThat(page).hasURL(Pattern.compile(".*/about$"));
+        assertThat(page.getByText("Discard your message?")).not().isVisible();
+    }
+
+    private Locator field(String label) {
+        return page.getByLabel(label, new Page.GetByLabelOptions().setExact(true));
+    }
+
+    private Locator sendButton() {
+        return page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send").setExact(true));
+    }
+}
